local config = {
  ui_story_5050_50500001_1_dialog_content = "<color=#e8d9bb>Menghasilkan adegan...</color>",
  ui_story_5050_50500001_2_dialog_content = "<color=#e8d9bb>Membuat skrip akhir...</color>",
  ui_story_5050_50500001_3_dialog_content = "<color=#e8d9bb>Selamat datang ke <color=#FFB400>Simulator Pelatihan Co-op</color>.</color>",
  ui_story_5050_50500001_4_dialog_content = "Sulit dipercaya, tapi tempat ini identik dengan Umbraton yang sebenarnya. Bahkan penduduk yang lalu lalang di jalanan telah disimulasikan dengan sempurna.",
  ui_story_5050_50500001_5_dialog_content = "Sayangnya, Anda tidak dapat melakukan percakapan normal dengan semua penduduk kota.",
  ui_story_5050_50500001_6_dialog_content = "Tampaknya semua bangunan bisa diakses, dan kita bisa mencari target di berbagai zona.",
  ui_story_5050_50500001_7_dialog_content = "Tapi ini mungkin mengurangi efisiensi kami, karena banyak tempat yang tidak berguna untuk misi.",
  ui_story_5050_50500001_8_dialog_content = "Tidak masalah—kami dapat mengirim 01 dan yang lainnya untuk mencari kami.",
  ui_story_5050_50500001_9_dialog_content = "Teman-teman, ini bukan waktunya untuk olok-olok kosong. Berdiri di sekitar alih-alih mengambil tindakan segera? Nah, itu bukan cara ksatria melakukan sesuatu.",
  ui_story_5050_50500001_10_dialog_content = "Jangan lupa mengapa kita ada di simulator ini. Tidak peduli seberapa besar beban kerja Anda, Anda harus memulai dari suatu tempat.",
  ui_story_5050_50500001_11_dialog_content = "Sangat benar, tetapi melakukan pekerjaan yang tidak berguna juga membuang-buang waktu. Bukankah desain ini agak sia-sia?",
  ui_story_5050_50500001_12_dialog_content = "Aku juga tidak tahu apa yang \"dia\" pikirkan ...",
  ui_story_5050_50500101_1_dialog_content = "<color=#e8d9bb>Beberapa waktu lalu...</color>",
  ui_story_5050_50500101_2_dialog_content = "Apa yang begitu penting sehingga Anda merasa perlu menelepon kami selama waktu istirahat?",
  ui_story_5050_50500101_3_dialog_content = "Heehee, mari kita lihat—semua tim ada di sini!",
  ui_story_5050_50500101_4_dialog_content = "Bisakah Anda berhenti dengan tawa sinis? Kau membuatku takut! Ini sebaiknya menjadi sesuatu yang utama bagi Anda untuk mengambil istirahat semua orang seperti ini.",
  ui_story_5050_50500101_5_dialog_content = "Tenang, semuanya. Saya sebenarnya punya kabar baik untuk Anda semua.",
  ui_story_5050_50500101_6_dialog_content = "Saya tahu lebih baik daripada siapa pun bahwa waktu istirahat adalah waktu yang paling berharga, jadi saya akan membuatnya sesingkat mungkin. Pada dasarnya, saya telah membuat versi baru dari Battle Simulator.",
  ui_story_5050_50500101_7_dialog_content = "Simulatornya? Anda ingin kami melakukan pelatihan tempur sekarang?",
  ui_story_5050_50500101_8_dialog_content = "Itu dia! Tapi versi ini berbeda dari latihan pertempuran dasar yang Anda lakukan sebelumnya, karena pertempuran hanyalah salah satu bagian darinya.",
  ui_story_5050_50500101_9_dialog_content = "Saya menambahkan permainan — batuk, maksud saya, saya merancang tumpukan pencarian eksplorasi peta, misi kerja sama, dan tahapan teka-teki.",
  ui_story_5050_50500101_10_dialog_content = "Kemenangan tidak selalu dimenangkan melalui kekerasan. Kerja tim dan kerja otak juga sangat penting.",
  ui_story_5050_50500101_11_dialog_content = "Dibandingkan dengan simulator pertempuran tradisional, saya percaya Simulator Pelatihan Co-op ini memiliki potensi untuk melatih kemampuan semua orang secara komprehensif.",
  ui_story_5050_50500101_12_dialog_content = "Itulah mengapa saya ingin mengundang semua orang untuk mencobanya—Anda juga akan membantu saya dalam pengujian pada saat yang sama!",
  ui_story_5050_50500101_13_dialog_content = "Apa? Anda bahkan belum mengujinya?",
  ui_story_5050_50500101_14_dialog_content = "Saya melakukan beberapa pengujian sederhana sendiri, tetapi saya membutuhkan lebih banyak orang untuk melakukan beberapa pengujian mendalam untuk saya.",
  ui_story_5050_50500101_15_dialog_content = "Yakinlah bahwa sim pelatihan ini tidak akan memengaruhi hasil sebenarnya dari Latihan Militer Gabungan—itu benar-benar hanya permintaan pribadi dari Anda!",
  ui_story_5050_50500101_16_dialog_content = "Saya harus mengakui bahwa ini sebenarnya adalah kesempatan langka, dan sejujurnya, kami juga sangat membutuhkan beberapa pelatihan tambahan.",
  ui_story_5050_50500101_17_dialog_content = "Jika ini memang kesempatan untuk latihan ekstra, kita tidak boleh melewatkannya begitu saja. Secara pribadi, saya tidak keberatan sama sekali.",
  ui_story_5050_50500101_18_dialog_content = "Jika semua orang ikut, mari kita mulai menggambar sedotan. Karena sifat teka-teki yang akan Anda tangani, hanya dua tim yang dapat masuk sekaligus.",
  ui_story_5050_50500101_19_dialog_content = "<color=#e8d9bb>Semua orang dengan cepat mulai menggambar sedotan untuk memutuskan tim mana yang akan pergi lebih dulu.</color>",
  ui_story_5050_50500101_20_dialog_content = "Coba saya lihat... Baiklah, Tim Twilight dan Tim Yingel—kamu bangun duluan!",
  ui_story_5050_50500101_21_dialog_content = "Hah, bagus sekali. Itu baik-baik saja oleh saya.",
  ui_story_5050_50500101_22_dialog_content = "Aku seharusnya bisa belajar banyak dari latihan bersama seorang kapten ksatria.",
  ui_story_5050_50500101_23_dialog_content = "Jadi, tim lain harus pergi sekarang—kamu tidak ingin melihat jawabannya sebelum mendapat kesempatan untuk mencobanya sendiri, bukan?",
  ui_story_5050_50500101_24_dialog_content = "Tanpa basa-basi lagi, mari kita mulai!",
  ui_story_5050_50500101_25_dialog_content = "Ini bukan latihan pertempuran biasa. Apa aturannya?",
  ui_story_5050_50500101_26_dialog_content = "Oh, benar, saya hampir lupa tentang itu... Tapi begitu Anda masuk, Anda akan menyadari sendiri bahwa peta kali ini terus berubah.",
  ui_story_5050_50500101_27_dialog_content = "Maksudmu ada peta yang berbeda?",
  ui_story_5050_50500101_28_dialog_content = "Saya telah merancang total <color=#FFB400>enam tahap utama</color>, masing-masing berdasarkan wilayah yang berbeda.",
  ui_story_5050_50500101_29_dialog_content = "Setiap orang perlu menjelajahi peta dan menyelesaikan panggung <color=#FFB400>pencarian</color>. Tujuan Anda adalah mencapai garis finis dan mengklaim semua perlengkapan dan hadiah!",
  ui_story_5050_50500101_30_dialog_content = "Anda akan dilengkapi dengan komunikator untuk simulasi ini, memungkinkan Anda berkomunikasi dari jarak jauh.",
  ui_story_5050_50500101_31_dialog_content = "Kedengarannya cukup mudah, seperti permainan.",
  ui_story_5050_50500101_32_dialog_content = "J-Jangan terlalu fokus pada detail kecil ini, itu tidak akan sesederhana yang kamu bayangkan.",
  ui_story_5050_50500101_33_dialog_content = "Kedua tim perlu bekerja sama untuk mengoperasikan mekanisme tertentu di area khusus. Ini akan menjadi saat kemampuan Anda untuk bekerja sama diuji!",
  ui_story_5050_50500101_34_dialog_content = "Semuanya masih terdengar agak ambigu bagi saya. Mari masuk ke simulator dan lihat sendiri.",
  ui_story_5050_50500101_35_dialog_content = "Benar, saya bisa membicarakan detailnya selamanya! Ayo! Setelah Anda masuk ke sana, jelajahi dengan kecepatan Anda sendiri dan Anda akan segera mengetahui semua yang perlu diketahui.",
  ui_story_5050_50500101_36_dialog_content = "Karena setiap gedung bisa diakses sesuka hati, sepertinya kita harus mengunjunginya satu per satu.",
  ui_story_5050_50500101_37_dialog_content = "Hai! Bisakah semua orang mendengarku?",
  ui_story_5050_50500101_38_dialog_content = "Lihat Poin Quest dan Poin Sumber Daya di peta? Saya telah menyesuaikan area utama ini sehingga mereka akan secara otomatis menanyakan lokasi mereka kepada Anda.",
  ui_story_5050_50500101_39_dialog_content = "Gronru dapat mendengar semua yang kami katakan?",
  ui_story_5050_50500101_40_dialog_content = "Ini seharusnya sangat meningkatkan efisiensi, sehingga tim lain tidak akan menunggu terlalu lama di luar.",
  ui_story_5050_50500101_41_dialog_content = "Terima kasih.",
  ui_story_5050_50500101_42_dialog_content = "Hehe, saya benar-benar tidak bermaksud seperti itu selama proses pengembangan! Ayo, semuanya—kalian bisa melakukannya!",
  ui_story_5050_50500101_43_dialog_content = "Mari kita mulai juga, dan cobalah untuk tidak melewatkan area yang ditandai ini.",
  ui_story_5050_50500101_44_dialog_content = "Setiap ruangan yang bisa dimasuki berbeda dengan rekannya di Umbraton asli, jadi ekstra hati-hati.",
  ui_story_5050_50500101_45_dialog_content = "Tampaknya ada pencarian khusus di antara mereka. May Dewa Cahaya memberkati Anda.",
  ui_story_5050_50500101_46_dialog_content = "Tidak apa-apa, aku punya ini.",
  ui_story_5050_50500101_47_dialog_content = "Baiklah, biarkan semangat kita melambung ke batas langit! Ayo selesaikan ini dalam satu gerakan!",
  ui_story_5050_50500102_1_dialog_content = "Saya pikir kita akan mencapai tahap berikutnya. Apakah semua orang masih dalam kondisi prima?",
  ui_story_5050_50500102_2_dialog_content = "Tidak ada masalah di sini.",
  ui_story_5050_50500102_3_dialog_content = "Kami juga baik.",
  ui_story_5050_50500102_4_dialog_content = "Saya secara bertahap memahami seluk beluk pelatihan ini. Dengan semua jenis tahapan yang berbeda, mereka bisa jadi menantang.",
  ui_story_5050_50500102_5_dialog_content = "Kukira Gronru merancang tahap pertama untuk membiarkan kita mengalami aturan. Tahap selanjutnya mungkin tidak semudah itu.",
  ui_story_5050_50500102_6_dialog_content = "Aku setuju.",
  ui_story_5050_50500102_7_dialog_content = "Ha ha! Mari kita fokus pada apa yang perlu kita lakukan, apa pun yang menghadang kita.",
  ui_story_5050_50500102_8_dialog_content = "Jadi semuanya, maju ke tahap selanjutnya!",
  ui_story_5050_50500201_1_dialog_content = "Ini... PlayerNameini Soroz!",
  ui_story_5050_50500201_2_dialog_content = "Aku tidak percaya dia bahkan memiliki cetak birunya di sini.",
  ui_story_5050_50500201_3_dialog_content = "Gronru sangat kompeten. Jangan pernah meremehkan dia.",
  ui_story_5050_50500201_4_dialog_content = "Kami mempunyai masalah.",
  ui_story_5050_50500201_5_dialog_content = "Sepertinya ini ruang kontrol utama, tapi pintunya disegel. Itu artinya kita tidak bisa langsung pergi ke lokasi lain di Soroz.",
  ui_story_5050_50500201_6_dialog_content = "Tidak mungkin panggung ini hanya terbatas pada satu ruangan. Pasti ada sesuatu yang tersembunyi di sekitar sini, seperti petunjuk atau semacam mekanisme.",
  ui_story_5050_50500201_7_dialog_content = "Jadi begitu. Cari saja tempatnya.",
  ui_story_5050_50500201_8_dialog_content = "Bagaimana menurutmu, Yingel?",
  ui_story_5050_50500201_9_dialog_content = "Oh, saya tidak berpikir Anda akan tertarik mendengar pendapat saya. Ruang kontrol utama hampir tidak memiliki perlengkapan atau perabotan apa pun, jadi satu-satunya tempat untuk menyembunyikan petunjuk adalah di panel kontrol.",
  ui_story_5050_50500201_10_dialog_content = "Anda memukul paku di kepala! Saya rasa panel kontrolnya juga cukup mencurigakan.",
  ui_story_5050_50500201_11_dialog_content = "Yingel benar, ada kotak mekanis di bawah panel.",
  ui_story_5050_50500201_12_dialog_content = "Saya tahu ini hanyalah realitas virtual, tetapi kotak ini indah.",
  ui_story_5050_50500201_13_dialog_content = "Tidak ada tempat untuk memasukkan kata sandi atau membukanya. Mungkin kita perlu membukanya melalui metode lain?",
  ui_story_5050_50500201_14_dialog_content = "Hmm, saya pernah melihat item eksperimen serupa sebelumnya. Mungkin itu dikendalikan suara.",
  ui_story_5050_50500201_15_dialog_content = "Dikendalikan suara? Itu artinya masih membutuhkan kata sandi. Axelia, apakah Anda ingin mencobanya?",
  ui_story_5050_50500201_16_dialog_content = "Hmm... Kata sandi, ruang kendali utama.",
  ui_story_5050_50500201_17_dialog_content = "Kata kunci Salah. Silakan coba lagi.",
  ui_story_5050_50500201_18_dialog_content = "Sandi, Soroz.",
  ui_story_5050_50500201_19_dialog_content = "Kata kunci Salah. Silakan coba lagi.",
  ui_story_5050_50500201_20_dialog_content = "Menebak secara acak sepertinya bukan solusi yang layak. Apakah ada petunjuk lain di panel?",
  ui_story_5050_50500201_21_dialog_content = "... Hmm, saya menemukan petunjuk di sini yang terlihat seperti kata sandi.",
  ui_story_5050_50500201_22_dialog_content = "Itu hebat, Leo. Nah, jangan buang waktu lagi...",
  ui_story_5050_50500201_23_dialog_content = "Yingel, mungkin Anda harus membacanya.",
  ui_story_5050_50500201_24_dialog_content = "Hmm? Baik-baik saja maka. Mari saya lihat.",
  ui_story_5050_50500201_25_dialog_content = "...",
  ui_story_5050_50500201_26_dialog_content = "Apa masalahnya, Yingel? Tolong bacakan dengan cepat.",
  ui_story_5050_50500201_27_dialog_content = "Surga, apakah itu sesuatu yang memalukan?",
  ui_story_5050_50500201_28_dialog_content = "(Pencarian adalah yang terpenting, tidak ada hal lain yang penting...!)",
  ui_story_5050_50500201_29_dialog_content = "Kata sandi, \"Siapa yang terkuat di negeri ini? Gadis cantik berkilau yang spektakuler, Gronru, dari dunia game! Kira-Kira!\"",
  ui_story_5050_50500201_30_dialog_content = "...",
  ui_story_5050_50500201_31_dialog_content = "...",
  ui_story_5050_50500201_32_dialog_content = "Saya benar-benar minta maaf.",
  ui_story_5050_50500201_33_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_5050_50500201_34_dialog_content = "<size=45>Apa itu?!</size>",
  ui_story_5050_50500201_35_dialog_content = "Itu gempa, ya?",
  ui_story_5050_50500201_36_dialog_content = "<size=45>Pertahankan pijakan Anda, semuanya! Pegang aku!</size>",
  ui_story_5050_50500201_37_dialog_content = "Perintah buka kunci diaktifkan. Harap pisahkan ke dalam tim Anda masing-masing di kedua sisi ruangan. Teleportasi dalam lima belas detik—",
  ui_story_5050_50500201_38_dialog_content = "Ugh!",
  ui_story_5050_50500201_39_dialog_content = "*Batuk-batuk*",
  ui_story_5050_50500201_40_dialog_content = "Sepertinya kita telah dipindahkan ke ruangan lain. Jika saya tidak salah, itu seharusnya berada di suatu tempat yang mirip dengan lounge.",
  ui_story_5050_50500201_41_dialog_content = "Kenapa Nona Yingel Dan Axelia tidak di sini?",
  ui_story_5050_50500201_42_dialog_content = "Leo, Bisakah kamu mendengarku?",
  ui_story_5050_50500201_43_dialog_content = "Sepertinya kami ditempatkan di ruangan yang berbeda. Apakah kamu baik-baik saja di sana?",
  ui_story_5050_50500201_44_dialog_content = "Kami baik-baik saja. Jadi, inilah gunanya komunikator.",
  ui_story_5050_50500201_45_dialog_content = "Ada sesuatu yang harus Anda ketahui. Jika kami ingin terus maju, tampaknya kami membutuhkan dukungan Anda.",
  ui_story_5050_50500201_46_dialog_content = "Apakah ini kerja sama yang dia sebutkan sebelumnya?",
  ui_story_5050_50500201_47_dialog_content = "Saya khawatir begitu, harap selesaikan misi Anda sesegera mungkin.",
  ui_story_5050_50500201_48_dialog_content = "Hmm, mari kita mulai secepat mungkin.",
  ui_story_5050_50500201_49_dialog_content = "...",
  ui_story_5050_50500201_50_dialog_content = "Apa yang salah, Axelia? Apakah kamu baik - baik saja?",
  ui_story_5050_50500201_51_dialog_content = "Tidak apa-apa, aku hanya tersandung selama teleportasi. Ayo pergi.",
  ui_story_5050_50500202_1_dialog_content = "Hal-hal telah berjalan cukup lancar sejauh ini. Apakah kalian semua baik-baik saja?",
  ui_story_5050_50500202_2_dialog_content = "Jangan khawatir, aku fi—batuk, batuk.",
  ui_story_5050_50500202_3_dialog_content = "Yakin?",
  ui_story_5050_50500202_4_dialog_content = "Zhao, jika Anda merasa tidak enak badan, pastikan untuk memberi tahu kami kapan saja.",
  ui_story_5050_50500202_5_dialog_content = "Hehe, aku tidak rapuh, jangan khawatir.",
  ui_story_5050_50500202_6_dialog_content = "Leo, kita hanya perlu mempertahankan kecepatan kita saat ini. Tidak perlu terburu-buru.",
  ui_story_5050_50500202_7_dialog_content = "Ini pelatihan, bukan? Bagaimana kita bisa memperlakukannya dengan santai, terutama saat Tim Yingel apakah memberikan semuanya?",
  ui_story_5050_50500202_8_dialog_content = "Ya, dan sekarang, karena dia, kedua belah pihak bekerja keras untuk mengatasi tantangan ini.",
  ui_story_5050_50500202_9_dialog_content = "Baiklah, karena semuanya baik-baik saja, mari kita lanjutkan.",
  ui_story_5050_50500203_1_dialog_content = "Kita harus bisa menyelesaikan tahap ini segera.",
  ui_story_5050_50500203_2_dialog_content = "Benar, kita sudah bisa melihat pintu keluar.",
  ui_story_5050_50500203_3_dialog_content = "Yingel, bagaimana perkembangan Anda?",
  ui_story_5050_50500203_4_dialog_content = "Semuanya berjalan lancar saat ini. Kami hampir di pintu keluar.",
  ui_story_5050_50500203_5_dialog_content = "Terima kasih untuk kalian semua, itu.",
  ui_story_5050_50500203_6_dialog_content = "Kesulitan telah meningkat secara signifikan dibandingkan sebelumnya. Bahkan Eclipsites kali ini lebih kuat.",
  ui_story_5050_50500203_7_dialog_content = "Bukankah itu yang terbaik? Ketika datang ke pelatihan, Eclipsites biasa tidak memotongnya lagi.",
  ui_story_5050_50500203_8_dialog_content = "Namun, aspek pencarian dan pengumpulan sumber daya telah berjalan lancar sejauh ini, jadi pertahankan, semuanya.",
  ui_story_5050_50500203_9_dialog_content = "Tahap selanjutnya mungkin lebih menantang.",
  ui_story_5050_50500204_1_dialog_content = "Omong-omong, saya tidak menyangka akan menemukan kamar yang begitu menarik di Soroz.",
  ui_story_5050_50500204_2_dialog_content = "Nah, jika Caelestite itu bisa hidup di Colossus ini dan bahkan menerima banyak tamu di sini, tak heran jika fasilitasnya terbilang lengkap.",
  ui_story_5050_50500204_3_dialog_content = "...",
  ui_story_5050_50500204_4_dialog_content = "Axelia, apakah ini imajinasi saya, atau apakah Anda merasa sedikit aneh?",
  ui_story_5050_50500204_5_dialog_content = "Saya baik-baik saja. Semuanya baik-baik saja.",
  ui_story_5050_50500204_6_dialog_content = "Apa kamu yakin? Jika Anda merasa tidak enak badan, beri tahu kami.",
  ui_story_5050_50500204_7_dialog_content = "Saya yakin. Saya memiliki banyak istirahat sebelum memasuki simulator, dan saya dapat mengambil lebih banyak dari apa yang telah kami lalui sejauh ini.",
  ui_story_5050_50500204_8_dialog_content = "Mari kita fokus pada tugas yang ada.",
  ui_story_5050_50500204_9_dialog_content = "Jika Axelia mengatakan demikian, ayo cepat maju.",
  ui_story_5050_50500204_10_dialog_content = "... Hmm. Namun, jangan memaksakan diri terlalu keras.",
  ui_story_5050_50500205_1_dialog_content = "Keluar dari tahap ini harus di depan.",
  ui_story_5050_50500205_2_dialog_content = "Anatoli, apakah kamu menggambar peta?",
  ui_story_5050_50500205_3_dialog_content = "Ya, saya telah membuat catatan lengkap tentang medan saat ini.",
  ui_story_5050_50500205_4_dialog_content = "Tapi ini hanya kebiasaan pribadi saya. Saya khawatir itu tidak akan banyak berguna.",
  ui_story_5050_50500205_5_dialog_content = "Dalam pertempuran yang sebenarnya, merupakan kebiasaan yang baik untuk segera merencanakan rute pelarian alternatif dalam keadaan darurat.",
  ui_story_5050_50500205_6_dialog_content = "Huh...",
  ui_story_5050_50500205_7_dialog_content = "Axelia, mari kita istirahat. Tidak perlu bagi kita untuk memaksakan diri kita sendiri.",
  ui_story_5050_50500205_8_dialog_content = "Benar-benar tidak perlu. Tim Leo sudah melaju ke tahap berikutnya. Tidak ada alasan bagus mengapa kita harus tertinggal di belakang mereka.",
  ui_story_5050_50500205_9_dialog_content = "Selain itu, ini adalah latihan kerja sama, jadi kita tidak boleh menyebabkan penundaan yang tidak perlu.",
  ui_story_5050_50500205_10_dialog_content = "Nah, jika Anda bersikeras, mari kita lanjutkan ke tahap selanjutnya.",
  ui_story_5050_50500205_11_dialog_content = "Tetapi jangan memaksakan diri—beri tahu saya jika Anda perlu istirahat.",
  ui_story_5050_50500205_12_dialog_content = "Jika sesuatu terjadi padamu, itu akan mempengaruhi kemajuan kita lebih dari istirahat sejenak.",
  ui_story_5050_50500205_13_dialog_content = "Aku mengerti.",
  ui_story_5050_50500301_1_dialog_content = "Apakah ini Kota Gannon?",
  ui_story_5050_50500301_2_dialog_content = "Saya sangat merindukan tempat ini. Sudah lama sejak saya kembali ke Kota Gannon.",
  ui_story_5050_50500301_3_dialog_content = "Ini memalukan, tetapi saya telah memberikan sedekah di seluruh benua untuk waktu yang lama dan belum pernah mengunjungi Kota Gannon sama sekali.",
  ui_story_5050_50500301_4_dialog_content = "Aku juga merasa seperti itu.",
  ui_story_5050_50500301_5_dialog_content = "Saya praktis tumbuh di sini, dan meskipun saya juga telah melalui banyak hal, itu masih memiliki tempat khusus di hati saya.",
  ui_story_5050_50500301_6_dialog_content = "Sepertinya Anda tidak melakukannya dengan baik. Bagaimana Anda bertahan dalam pelatihan di barak Illumina?",
  ui_story_5050_50500301_7_dialog_content = "Jika bukan karena pengalaman sadis garis batas itu, saya tidak akan menjadi seperti sekarang ini. Uhuk uhuk...",
  ui_story_5050_50500301_8_dialog_content = "Saya secara bertahap mengembangkan gaya bertarung saya sendiri setelah didorong ke dalam berbagai skenario pertempuran.",
  ui_story_5050_50500301_9_dialog_content = "Saya juga belajar bagaimana menyusun strategi dan memerintahkan pertempuran.",
  ui_story_5050_50500301_10_dialog_content = "Itu benar-benar luar biasa, saya harap cahaya selalu menyinari Anda.",
  ui_story_5050_50500301_11_dialog_content = "Hai! Kedengarannya kalian sedang mengobrol hebat di sana!",
  ui_story_5050_50500301_12_dialog_content = "Sekadar tip ramah, tidak akan ada segmen pendukung pada tahap ini, jadi Anda dapat melanjutkan dan mengatur strategi sendiri.",
  ui_story_5050_50500301_13_dialog_content = "Aku mengerti.",
  ui_story_5050_50500301_14_dialog_content = "Jadi, mari kita maju dengan sekuat tenaga.",
  ui_story_5050_50500302_1_dialog_content = "Batuk, batuk... Batuk, batuk, batuk...",
  ui_story_5050_50500302_2_dialog_content = "Eclipsites jelas jauh lebih kuat dalam pertempuran barusan. Mari kita istirahat.",
  ui_story_5050_50500302_3_dialog_content = "... Anda tidak perlu berhenti demi saya. Aku baik-baik saja.",
  ui_story_5050_50500302_4_dialog_content = "Aku tidak mengatakan itu karena kamu.",
  ui_story_5050_50500302_5_dialog_content = "Anda tidak perlu terlalu perhatian, Kapten Leo. Tugas di tangan sangat penting, meskipun saya menghargai kebaikan Anda. Batuk...!",
  ui_story_5050_50500302_6_dialog_content = "Saat butuh istirahat, berusaha untuk melewatinya hanya akan membebani anggota tim lainnya.",
  ui_story_5050_50500302_7_dialog_content = "Bagaimana apanya? Apakah Anda mencoba mengatakan bahwa saya adalah beban?",
  ui_story_5050_50500302_8_dialog_content = "Oh! Tenang, semuanya, tolong.",
  ui_story_5050_50500302_9_dialog_content = "Niat Anda di sini semuanya baik. Kita semua adalah anak-anak Dewa Cahaya, jadi tolong jaga keharmonisan.",
  ui_story_5050_50500302_10_dialog_content = "...",
  ui_story_5050_50500302_11_dialog_content = "Tidak apa-apa. Saya tahu Anda tidak bisa memaksa orang lain untuk bertindak bertentangan dengan keinginan mereka. Ayo lanjutkan.",
  ui_story_5050_50500303_1_dialog_content = "Syukurlah—sepertinya kita akan mencapai pintu keluar.",
  ui_story_5050_50500303_2_dialog_content = "...",
  ui_story_5050_50500303_3_dialog_content = "(Leo memiliki kepribadian yang kuat, dan Zhao kadang-kadang bisa menjadi sangat sensitif karena rangsangan fisiknya, meskipun ia tampaknya membumi sebagian besar waktu.)",
  ui_story_5050_50500303_4_dialog_content = "(Suasananya sedikit tegang sejak tadi. Saya harap keduanya tidak saling berhadapan.)",
  ui_story_5050_50500303_5_dialog_content = "Hah, kita akan segera mencapai akhir tantangan. Meskipun kesulitannya mungkin meningkat, kami lebih dari mampu untuk keluar dari kemenangan ini.",
  ui_story_5050_50500303_6_dialog_content = "Namun, pertempuran juga merupakan bentuk seni, dan kemenangan tidak bisa begitu saja dimenangkan oleh mereka yang menyerang dengan sengit, dengan tombak di tangan. Tanpa seseorang di belakang mereka untuk menyusun strategi, kekalahan tidak bisa dihindari.",
  ui_story_5050_50500303_7_dialog_content = "Joseph, Zhao, kami bekerja sama dengan indah di luar sana.",
  ui_story_5050_50500303_8_dialog_content = "Tidak perlu terlalu pesimis atau kritis terhadap diri sendiri karena hal-hal yang tidak bisa kita tangani saat ini.",
  ui_story_5050_50500303_9_dialog_content = "Masih banyak hal lain yang bisa kita lakukan.",
  ui_story_5050_50500303_10_dialog_content = "Benar. Terima kasih.",
  ui_story_5050_50500303_11_dialog_content = "Saya hanya bereaksi sedikit berlebihan, tolong jangan terlalu memikirkannya.",
  ui_story_5050_50500303_12_dialog_content = "Mengapa saya harus? Kita semua rekan satu tim di sini, mengapa repot-repot dengan hal-hal sepele seperti itu?",
  ui_story_5050_50500303_13_dialog_content = "Kami tidak tahu apakah akan ada tantangan baru di tahap selanjutnya. Kita perlu berhati-hati saat kita bergerak maju.",
  ui_story_5050_50500401_1_dialog_content = "Kota Gannon?",
  ui_story_5050_50500401_2_dialog_content = "Sepertinya begitu.",
  ui_story_5050_50500401_3_dialog_content = "Jika saya ingat dengan benar, Anda dan Axelia apakah keduanya penduduk asli Gannon, benar?",
  ui_story_5050_50500401_4_dialog_content = "Kecerdasan Anda sempurna seperti biasa. Memang, kami lahir di Kota Gannon.",
  ui_story_5050_50500401_5_dialog_content = "Seperti halnya saya.",
  ui_story_5050_50500401_6_dialog_content = "Jadi kita bertiga seharusnya memiliki keuntungan yang cukup besar di peta ini.",
  ui_story_5050_50500401_7_dialog_content = "Ya. Tempat ini tentu penuh dengan banyak kenangan.",
  ui_story_5050_50500401_8_dialog_content = "Ini juga tempat saya bertemu Yingel dan Sean.",
  ui_story_5050_50500401_9_dialog_content = "Meskipun hidup membosankan saat itu, kami masih merasa seperti keluarga kecil.",
  ui_story_5050_50500401_10_dialog_content = "Apakah Anda sampai ini, Axelia?",
  ui_story_5050_50500401_11_dialog_content = "Jangan khawatir. Saya baik-baik saja.",
  ui_story_5050_50500401_12_dialog_content = "Mari kita pergi. Kita seharusnya tidak membuat Leo dan timnya menunggu terlalu lama.",
  ui_story_5050_50500401_13_dialog_content = "...",
  ui_story_5050_50500402_1_dialog_content = "Bisakah kamu tetap bertahan?",
  ui_story_5050_50500402_2_dialog_content = "Bukan masalah.",
  ui_story_5050_50500402_3_dialog_content = "... Saya akan baik baik saja.",
  ui_story_5050_50500402_4_dialog_content = "Simulasi pertempuran Eclipsite cukup standar, saya tidak pernah membayangkan pencarian aneh itu akan sangat rumit.",
  ui_story_5050_50500402_5_dialog_content = "Saya telah mengamati tempat itu sejak kami masuk, dan telah memperhatikan bahwa titik arahnya sangat berbeda dari pertemuan di kehidupan nyata.",
  ui_story_5050_50500402_6_dialog_content = "Meskipun konsep pencarian, sumber daya, kerja sama, dan sebagainya ada dalam situasi pertempuran yang sebenarnya, mereka tidak memiliki sifat mekanis yang kaku.",
  ui_story_5050_50500402_7_dialog_content = "Apa maksudmu?",
  ui_story_5050_50500402_8_dialog_content = "Menurut pendapat pribadi saya, Gronru telah menyalin dan menerapkan beberapa elemen gameplay komprehensif dari video game tertentu.",
  ui_story_5050_50500402_9_dialog_content = "Saya tidak terkejut... Kedengarannya seperti sesuatu yang akan dia lakukan.",
  ui_story_5050_50500402_10_dialog_content = "Dan saya berspekulasi bahwa menambahkan mekanisme rumit seperti itu ke simulator pertempuran mungkin akan menambah beban yang lebih tinggi pada tubuh penguji.",
  ui_story_5050_50500402_11_dialog_content = "Terutama penguji dengan tingkat kebugaran jasmani yang lebih rendah.",
  ui_story_5050_50500402_12_dialog_content = "Itu hanya teoriku, tapi performa Axelia kurang, dan menurutku dia lebih mampu dari ini.",
  ui_story_5050_50500402_13_dialog_content = "Menakjubkan. Aku tidak akan pernah bisa menangkapnya...",
  ui_story_5050_50500402_14_dialog_content = "Axelia, apakah Anda ingin keluar dari simulator untuk sementara waktu? Kami tidak ingin tes ini memengaruhi kinerja Anda dalam Latihan Militer Gabungan yang sebenarnya...",
  ui_story_5050_50500402_15_dialog_content = "Ini tidak seserius itu semua.",
  ui_story_5050_50500402_16_dialog_content = "Itu tidak akan mempengaruhi latihan, saya yakin akan hal itu.",
  ui_story_5050_50500402_17_dialog_content = "Baiklah kalau begitu, mari kita buat keputusan cepat dan bergerak maju secepat mungkin.",
  ui_story_5050_50500403_1_dialog_content = "Aku bisa melihat pintu keluar.",
  ui_story_5050_50500403_2_dialog_content = "Kami telah menyelesaikan sebagian besar tantangan, dan saat ini sepertinya tahap keempat akan segera berakhir.",
  ui_story_5050_50500403_3_dialog_content = "Kami sudah di sini begitu lama. PlayerName dan yang lain pasti sudah tidak sabar menunggu kita.",
  ui_story_5050_50500403_4_dialog_content = "Tidak ada yang bisa kita lakukan tentang itu. Meskipun hanya ada enam tahap, tes ini menghabiskan lebih banyak waktu dari yang saya perkirakan.",
  ui_story_5050_50500403_5_dialog_content = "Juga, Vice tahu banyak tentang mekanik, jadi PlayerName dan yang lain mungkin menyelesaikan tahapan ini lebih cepat dari kita.",
  ui_story_5050_50500403_6_dialog_content = "Tidak apa-apa, mari kita pergi dengan kecepatan kita sendiri.",
  ui_story_5050_50500403_7_dialog_content = "Maaf telah membuat semua orang mengkhawatirkanku selama ini...",
  ui_story_5050_50500403_8_dialog_content = "Yang penting kamu baik-baik saja.",
  ui_story_5050_50500403_9_dialog_content = "Mungkin kita bisa bergabung dengan mereka di tahap berikutnya.",
  ui_story_5050_50500501_1_dialog_content = "Sepertinya kita kembali ke tema Undercity yang diatur bersama di tahap ini.",
  ui_story_5050_50500501_2_dialog_content = "Yingel, apakah semuanya berjalan lancar di pihak Anda?",
  ui_story_5050_50500501_3_dialog_content = "Yap, semuanya baik untuk kita.",
  ui_story_5050_50500501_4_dialog_content = "Saya hanya ingin mengkonfirmasi satu hal dengan Anda... Apakah ada di antara Anda yang merasa tidak enak badan?",
  ui_story_5050_50500501_5_dialog_content = "... Mengapa Anda bertanya?",
  ui_story_5050_50500501_6_dialog_content = "Axelia merasa tidak enak selama ini.",
  ui_story_5050_50500501_7_dialog_content = "Saya menduga bahwa mekanisme yang terlalu rumit dari simulator ini menambah beban pada orang-orang dengan kondisi fisik yang lemah.",
  ui_story_5050_50500501_8_dialog_content = "Jadi itulah yang salah.",
  ui_story_5050_50500501_9_dialog_content = "Hmm, sebenarnya saya juga memperhatikan.",
  ui_story_5050_50500501_10_dialog_content = "Halo semuanya!",
  ui_story_5050_50500501_11_dialog_content = "Maaf, saya sudah menjalankan tes di simulator, baru mendengar percakapan Anda.",
  ui_story_5050_50500501_12_dialog_content = "Saya benar-benar tidak mempertimbangkan efek fisik yang mungkin dimiliki simulator pada penggunanya...",
  ui_story_5050_50500501_13_dialog_content = "Tapi tampaknya sebagian besar deduksi Anatoli benar.",
  ui_story_5050_50500501_14_dialog_content = "Ini adalah masalah yang relatif signifikan. Mungkin Zhao dan Axelia harus keluar dan istirahat?",
  ui_story_5050_50500501_15_dialog_content = "Tidak perlu.",
  ui_story_5050_50500501_16_dialog_content = "K-Kamu benar-benar bertekad?",
  ui_story_5050_50500501_17_dialog_content = "Saya memiliki keyakinan pada tubuh saya. Saya akan minta istirahat bila perlu.",
  ui_story_5050_50500501_18_dialog_content = "Sama.",
  ui_story_5050_50500501_19_dialog_content = "Kita mendekati akhir. Mari kita selesaikan ini dengan.",
  ui_story_5050_50500501_20_dialog_content = "Jika mereka bersikeras, mari kita hormati pendapat para pihak yang terlibat.",
  ui_story_5050_50500501_21_dialog_content = "Oke, saya juga akan mengawasi situasi semua orang setiap saat.",
  ui_story_5050_50500501_22_dialog_content = "Tahap ini tampaknya memiliki bagian membuka kunci kooperatif. Leo, kami mengandalkan Anda.",
  ui_story_5050_50500501_23_dialog_content = "Jangan khawatir, mari selesaikan ini sekaligus.",
  ui_story_5050_50500502_1_dialog_content = "Nampaknya stage ini bertemakan Undercity.",
  ui_story_5050_50500502_2_dialog_content = "Sepertinya kita akan membutuhkan Leo dan yang lainnya untuk membantu kami membuka jalan di depan sebelum kami dapat melewatinya.",
  ui_story_5050_50500502_3_dialog_content = "Benar. Mari kita istirahat di sini sambil menunggu.",
  ui_story_5050_50500502_4_dialog_content = "Huh...",
  ui_story_5050_50500502_5_dialog_content = "(Axelia sepertinya sangat lelah.)",
  ui_story_5050_50500502_6_dialog_content = "(Aku tidak pernah menyangka bahwa Aurorian kecil dari panti asuhan bertahun-tahun yang lalu akan tumbuh menjadi begitu kuat.)",
  ui_story_5050_50500502_7_dialog_content = "(Melihat ke belakang, sepertinya baru kemarin.)",
  ui_story_5050_50500502_8_dialog_content = "... Memikirkan sesuatu?",
  ui_story_5050_50500502_9_dialog_content = "Hanya mengingat masa lalu.",
  ui_story_5050_50500502_10_dialog_content = "Kenangan masa kecil?",
  ui_story_5050_50500502_11_dialog_content = "Kenapa bisa begitu?",
  ui_story_5050_50500502_12_dialog_content = "Jangan meremehkan jangkauan jaringan intelijen saya. Anda dan Axelia sudah saling kenal sejak kalian masih anak-anak. Saya tahu semua tentang itu.",
  ui_story_5050_50500502_13_dialog_content = "Ya, kami sudah saling kenal sejak kami masih sangat muda.",
  ui_story_5050_50500502_14_dialog_content = "Berkelahi bersama seorang kenalan lama yang benar-benar Anda percayai adalah hal yang patut ditiru, dari sudut pandang tertentu.",
  ui_story_5050_50500502_15_dialog_content = "Apakah Anda memiliki orang seperti itu?",
  ui_story_5050_50500502_16_dialog_content = "...",
  ui_story_5050_50500502_17_dialog_content = "Mari berhenti mengobrol untuk saat ini, kami tidak ingin membangunkannya.",
  ui_story_5050_50500503_1_dialog_content = "Meskipun ini tidak benar-benar memenuhi syarat sebagai pelatihan pertempuran intensif, simulasi ini tetap membutuhkan tenaga fisik yang signifikan. Apa kamu baik baik saja?",
  ui_story_5050_50500503_2_dialog_content = "Saya baik-baik saja. Zhao?",
  ui_story_5050_50500503_3_dialog_content = "Aku juga baik-baik saja.",
  ui_story_5050_50500503_4_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500503_5_dialog_content = "Tentang apa semua ini?",
  ui_story_5050_50500503_6_dialog_content = "Astaga! Maaf!",
  ui_story_5050_50500503_7_dialog_content = "Ini adalah bug yang diketahui... Terkadang, peta yang salah dimuat.",
  ui_story_5050_50500503_8_dialog_content = "Tapi jangan khawatir, itu tidak akan berdampak pada kemajuan Anda!",
  ui_story_5050_50500503_9_dialog_content = "Saya perhatikan sebelumnya bahwa ada celah yang jelas dalam hubungan antara beberapa ruangan di panggung.",
  ui_story_5050_50500503_10_dialog_content = "Tapi saya belum melihat celah ini di jalur di mana Anda bisa menemukan Eclipsites.",
  ui_story_5050_50500503_11_dialog_content = "Saya menduga semua kamar itu dibuat secara acak, benar?",
  ui_story_5050_50500503_12_dialog_content = "<size=45>!!!</size>",
  ui_story_5050_50500503_13_dialog_content = "Jangan mencoba menebak secara acak pemikiran sang desainer!",
  ui_story_5050_50500503_14_dialog_content = "Ini rahasia! Rahasia!",
  ui_story_5050_50500503_15_dialog_content = "Zhao, kekuatan pengamatanmu sangat tajam.",
  ui_story_5050_50500503_16_dialog_content = "Anda benar-benar layak atas reputasi Anda sebagai ahli strategi Illumina yang tak tertandingi, mampu menangkap detail kecil seperti itu.",
  ui_story_5050_50500503_17_dialog_content = "Itu sedikit berlebihan. Saya baru saja terbiasa mengamati detail di medan perang.",
  ui_story_5050_50500503_18_dialog_content = "Baiklah! Jangan khawatir tentang detail kecil ini, langsung saja ke tahap berikutnya dengan cepat! Tahap terakhir tidak akan mudah!",
  ui_story_5050_50500503_19_dialog_content = "Hehe, itu masih tidak akan membuat kita lebih baik! Ayo pergi!",
  ui_story_5050_50500504_1_dialog_content = "Sepertinya kita akan mencapai tahap akhir.",
  ui_story_5050_50500504_2_dialog_content = "Tahap akhir tidak akan mudah... Bersiaplah, semuanya.",
  ui_story_5050_50500504_3_dialog_content = "Yingel, bagaimana kabarmu di akhir? Apakah Anda sudah sampai di pintu keluar?",
  ui_story_5050_50500504_4_dialog_content = "Kami hampir sampai.",
  ui_story_5050_50500504_5_dialog_content = "Adalah Axelia Oke?",
  ui_story_5050_50500504_6_dialog_content = "Jangan khawatir, saya baru saja beristirahat dan merasa jauh lebih baik sekarang.",
  ui_story_5050_50500504_7_dialog_content = "Saya dalam performa terbaik dan siap menghadapi tantangan terakhir secara langsung.",
  ui_story_5050_50500504_8_dialog_content = "Hah, senang mendengarnya!",
  ui_story_5050_50500504_9_dialog_content = "Sampai jumpa di tahap akhir!",
  ui_story_5050_50500504_10_dialog_content = "Oke, mari kita bergerak maju dengan cepat.",
  ui_story_5050_50500601_1_dialog_content = "...",
  ui_story_5050_50500601_2_dialog_content = "Apa yang salah, Leo? Apakah kamu baik - baik saja?",
  ui_story_5050_50500601_3_dialog_content = "Tidak ada yang pernah menanyakan itu sebelumnya... Yakinlah, ketabahan saya tidak mengenal batas.",
  ui_story_5050_50500601_4_dialog_content = "Kapten Leo, apakah karena kita berada di Lumopolis?",
  ui_story_5050_50500601_5_dialog_content = "Anda dari Lumopolis. Peta ini pasti terasa sangat familiar bagi Anda.",
  ui_story_5050_50500601_6_dialog_content = "... Haha, dan aku belum pernah ada yang menebak apa yang kupikirkan dengan mudah sebelumnya.",
  ui_story_5050_50500601_7_dialog_content = "Anda benar, saya tidak dapat menyangkalnya—saya lahir di sini.",
  ui_story_5050_50500601_8_dialog_content = "Lumopolis telah memberi saya banyak hal, namun juga mengambil banyak hal dari saya.",
  ui_story_5050_50500601_9_dialog_content = "Seorang bangsawan yang dibuang dari Uptown ke daerah yang sangat dekat dengan Malam Abadi. Bahkan jika kamu mati, kamu tidak lebih dari mayat yang membusuk, tidak diratapi oleh siapa pun.",
  ui_story_5050_50500601_10_dialog_content = "Secara alami, saya memiliki banyak pengalaman yang tak terlupakan, tetapi itu juga perlahan mengubah cara berpikir saya.",
  ui_story_5050_50500601_11_dialog_content = "Leo...",
  ui_story_5050_50500601_12_dialog_content = "...",
  ui_story_5050_50500601_13_dialog_content = "Aku tidak bermaksud mengoceh seperti itu. Yang perlu Anda ketahui adalah bahwa saya saat ini hanya memiliki satu tujuan — untuk melawan Eclipsites dengan semua orang yang bersedia berdiri di samping saya.",
  ui_story_5050_50500601_14_dialog_content = "Kita dapat membicarakan hal-hal lain di waktu senggang kita ketika kita memiliki waktu luang di masa depan.",
  ui_story_5050_50500601_15_dialog_content = "Bagus sekali. Saya ingin mendengar lebih banyak.",
  ui_story_5050_50500601_16_dialog_content = "Leo, apakah kamu juga sudah sampai di Lumopolis disana?",
  ui_story_5050_50500601_17_dialog_content = "Ya, kami ada di peta Uptown.",
  ui_story_5050_50500601_18_dialog_content = "Kita harus bertemu menjelang akhir. Teruskan, semuanya.",
  ui_story_5050_50500601_19_dialog_content = "Kamu juga. Jaga keselamatan.",
  ui_story_5050_50500601_20_dialog_content = "Ayo bergerak!",
  ui_story_5050_50500602_1_dialog_content = "Apakah ini... Lumopolis?",
  ui_story_5050_50500602_2_dialog_content = "Saya belum pernah ke sini sebelumnya.",
  ui_story_5050_50500602_3_dialog_content = "Menilai dari tata letak di sini, ini seharusnya Lumopolis Bawah. Ini tentu memiliki gaya yang unik.",
  ui_story_5050_50500602_4_dialog_content = "Kami bertiga ditempatkan di Illumina. Kami belum sempat mengenal Lumopolis.",
  ui_story_5050_50500602_5_dialog_content = "Kita harus mengambil kesempatan ini untuk melihat-lihat.",
  ui_story_5050_50500602_6_dialog_content = "Lumopolis...",
  ui_story_5050_50500602_7_dialog_content = "Anatoli, apakah Anda memiliki sesuatu yang menentang Lumopolis?",
  ui_story_5050_50500602_8_dialog_content = "Saya menganggap diri saya seorang sentris dalam hal ini. Meskipun ikatan antara Illumina dan Lumopolis agak halus, saya tidak condong ke kedua sisi.",
  ui_story_5050_50500602_9_dialog_content = "Kita semua memiliki tujuan dan harapan yang sama untuk hari esok yang lebih cerah. Mengapa menggunakan faksi seperti itu untuk dengan sengaja menyebarkan permusuhan dan prasangka?",
  ui_story_5050_50500602_10_dialog_content = "Itulah jenis jawaban yang saya harapkan dari Anda.",
  ui_story_5050_50500602_11_dialog_content = "Tidak peduli dari mana Anda berasal atau dari faksi mana Anda berasal, kita semua sekarang hanya memiliki satu tujuan yang sama.",
  ui_story_5050_50500602_12_dialog_content = "Mungkin sesekali melihat masalah dari sudut pandang yang berbeda bisa membuat segalanya lebih mudah.",
  ui_story_5050_50500602_13_dialog_content = "Tahap akhir, harus menantang.",
  ui_story_5050_50500602_14_dialog_content = "Ya. Aku ingin tahu apakah akan ada tantangan panggung khusus...",
  ui_story_5050_50500602_15_dialog_content = "Ayo kita pergi!",
  ui_story_5050_50500603_1_dialog_content = "Leo! Kami akhirnya kembali bersama.",
  ui_story_5050_50500603_2_dialog_content = "Saya harus mengakui bahwa kami bekerja sama dengan sangat baik, jika tidak, kami tidak akan mencapai garis finis begitu cepat.",
  ui_story_5050_50500603_3_dialog_content = "Tapi saya tidak begitu mengerti beberapa pencarian. Itu sakit kepala.",
  ui_story_5050_50500603_4_dialog_content = "Itu semua berkat upaya bersama semua orang sehingga kami berhasil.",
  ui_story_5050_50500603_5_dialog_content = "Axelia, bagaimana kabarmu?",
  ui_story_5050_50500603_6_dialog_content = "Saya merasa seratus persen.",
  ui_story_5050_50500603_7_dialog_content = "Segala puji bagi Dewa Cahaya atas berkat-berkatnya. Kekuatan rasa saling percaya kamilah yang membuat perjalanan kami begitu sukses.",
  ui_story_5050_50500603_8_dialog_content = "Wow! Kerja bagus! Selamat telah mencapai garis finish!",
  ui_story_5050_50500603_9_dialog_content = "Apakah Anda menikmati pelatihan?",
  ui_story_5050_50500603_10_dialog_content = "Ini mungkin berbeda dari pelatihan praktis yang biasa Anda lakukan, tetapi juga membantu melatih berbagai kemampuan, membuatnya sama-sama bermanfaat.",
  ui_story_5050_50500603_11_dialog_content = "Ini adalah pengalaman langka bagi kami untuk menjadi lebih akrab dengan kemampuan satu sama lain melalui kerja sama yang erat.",
  ui_story_5050_50500603_12_dialog_content = "Heheh, klasik lagi Gronru produksi, dikembangkan selama beberapa hari dan malam tanpa tidur!",
  ui_story_5050_50500603_13_dialog_content = "Saran kecil lainnya — mungkin Anda harus mengerjakan ulang kata sandi yang dikontrol suara di peta Colossus.",
  ui_story_5050_50500603_14_dialog_content = "Hah? Oh...",
  ui_story_5050_50500603_15_dialog_content = "<size=45>Apa?!?! Aku tidak mengubahnya?!</size>",
  ui_story_5050_50500603_16_dialog_content = "<size=45>I-Itu hanya sesuatu yang aku tambahkan secara acak saat debugging!</size>",
  ui_story_5050_50500603_17_dialog_content = "Tidak apa-apa... Hanya sedikit dari kita yang tahu kata sandinya sekarang.",
  ui_story_5050_50500603_18_dialog_content = "Dan kemudian hanya ada Vice, Carleen, Dan PlayerName berikutnya.",
  ui_story_5050_50500603_19_dialog_content = "Anda tidak membuat saya merasa lebih baik.",
  ui_story_5050_50500603_20_dialog_content = "Ahem... Bagaimanapun, kerja bagus, semuanya. Jangan biarkan tim yang tersisa menunggu terlalu lama—persiapkan dirimu...",
  ui_story_5050_50500603_21_dialog_content = "<color=#e8d9bb>Gemuruh, gemuruh...</color>",
  ui_story_5050_50500603_22_dialog_content = "Apakah itu gempa bumi?",
  ui_story_5050_50500603_23_dialog_content = "... Apa yang sedang terjadi? Mengapa sistem tiba-tiba melaporkan kesalahan?!",
  ui_story_5050_50500603_24_dialog_content = "Perhatikan langkahmu, semuanya!",
  ui_story_5050_50500603_25_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500603_26_dialog_content = "Peta berubah.",
  ui_story_5050_50500603_27_dialog_content = "Itu semua adalah tahapan yang pernah kita lalui sebelumnya. Apakah ada yang salah dengan sistemnya?",
  ui_story_5050_50500603_28_dialog_content = "Aaah! Semuanya, tolong tunggu sebentar — saya sedang memperbaikinya!",
  ui_story_5050_50500603_29_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian…</color>",
  ui_story_5050_50500603_30_dialog_content = "Fiuh ... Seharusnya baik-baik saja sekarang.",
  ui_story_5050_50500603_31_dialog_content = "Maaf, mungkin ada beberapa bug kecil yang tertinggal di bagian terakhir.",
  ui_story_5050_50500603_32_dialog_content = "Saya kira saya tidak men-debug tahap akhir dengan cukup menyeluruh.",
  ui_story_5050_50500603_33_dialog_content = "Apakah hal itu di depan salah satu bug Anda juga?",
  ui_story_5050_50500603_34_dialog_content = "Hah? Apa?",
  ui_story_5050_50500603_35_dialog_content = "<anim type=Shake><size=45>Graah! Graaah!</size></anim>",
  ui_story_5050_50500603_36_dialog_content = "A-Apa itu?! Saya tidak ingat menambahkan hal seperti itu ke sim!",
  ui_story_5050_50500603_37_dialog_content = "Tidak ada pilihan selain menerimanya.",
  ui_story_5050_50500603_38_dialog_content = "Anggap saja sebagai sesi pelatihan dadakan! Ayo pergi!",
  ui_story_5050_50500604_1_dialog_content = "<size=45>Kerja bagus, semuanya! Selamat telah menyelesaikan stage!</size>",
  ui_story_5050_50500604_2_dialog_content = "Anda tahu, mengalahkan Eclipsite terakhir yang baru saja muncul dari langit biru jernih itu jauh lebih sulit daripada semua tahapan sebelumnya.",
  ui_story_5050_50500604_3_dialog_content = "Hah, tapi itu memang kesempatan langka untuk beberapa pelatihan tempur yang benar-benar menantang. Kita mungkin menghadapi musuh yang lebih kuat di medan perang.",
  ui_story_5050_50500604_4_dialog_content = "Memang. Bug itu lebih mengasyikkan daripada tahapan sebenarnya.",
  ui_story_5050_50500604_5_dialog_content = "K-Kamu tidak bisa mengatakan hal semacam itu kepada seorang desainer!",
  ui_story_5050_50500604_6_dialog_content = "Tapi apakah bertarung dengan Ironthorn Knights atau dalam Latihan Militer Gabungan, kerja sama sangat penting untuk pertempuran.",
  ui_story_5050_50500604_7_dialog_content = "Satu orang saja terbatas pada apa yang dapat mereka capai. Bahkan sebagai seorang pemimpin, bertarung sendirian sama saja seperti pohon muda yang goyah dalam kegelapan.",
  ui_story_5050_50500604_8_dialog_content = "Sahabat adalah cahaya, air, dan kekuatan agung yang dapat mengubah pohon muda menjadi pohon yang agung.",
  ui_story_5050_50500604_9_dialog_content = "Kemenangan kami didasarkan pada upaya masing-masing rekan kami.",
  ui_story_5050_50500604_10_dialog_content = "Tidak setiap hari ada yang mendengar Leo membuat pidato emosional seperti itu.",
  ui_story_5050_50500604_11_dialog_content = "Aku hanya mengungkapkan perasaanku.",
  ui_story_5050_50500604_12_dialog_content = "Saat menghadapi misi yang begitu rumit, satu orang seperti lalat tanpa kepala tanpa tim yang bekerja sama untuk tujuan bersama.",
  ui_story_5050_50500604_13_dialog_content = "Saya juga sangat berterima kasih atas bantuan semua orang.",
  ui_story_5050_50500604_14_dialog_content = "Aku hanya melakukan apa yang menurutku benar.",
  ui_story_5050_50500604_15_dialog_content = "Saat ini, marilah kita menerima kebaikan yang hangat ini dengan damai di hati kita. May Dewa Cahaya memberkati semua rekan tepercaya kami dan kami.",
  ui_story_5050_50500604_16_dialog_content = "Lantas, game apa yang menjadi dasar dari simulasi ini?",
  ui_story_5050_50500604_17_dialog_content = "Sebenarnya, itu adalah Sword of the—maksudku, aku mendesainnya sendiri!",
  ui_story_5050_50500604_18_dialog_content = "Oh. Itu sangat mengesankan.",
  ui_story_5050_50500604_19_dialog_content = "Namun lain kali, Anda harus memikirkan untuk menghapus logo pengembang asli dari aset game.",
  ui_story_5050_50500604_20_dialog_content = "<size=45>!!!</size>",
  ui_story_5050_50500604_21_dialog_content = "Apakah Anda menemukan semua kekurangan dalam permainan saya? Anda salah satu petugas intelijen yang tajam.",
  ui_story_5050_50500604_22_dialog_content = "Baiklah, jangan menggodanya. Ini adalah sesi latihan yang sangat berarti bagi kami semua.",
  ui_story_5050_50500604_23_dialog_content = "Mengapa belum PlayerName, Beretta, dan yang lainnya belum datang? Mereka pasti lelah menunggu.",
  ui_story_5050_50500604_24_dialog_content = "Ingat apa yang saya katakan, ada elemen eksplorasi dan pemecahan teka-teki di sim ini, jadi sebaiknya kita biarkan mereka menghindari potensi spoiler.",
  ui_story_5050_50500604_25_dialog_content = "Namun, tidak terlalu banyak masalah sistem selama proses pengujian, jadi menurut saya cukup berhasil!",
  ui_story_5050_50500604_26_dialog_content = "Jadi, mari kita biarkan PlayerName dan yang lainnya mengalami semuanya sendiri!",
  ui_story_5050_50500604_27_dialog_content = "Leo, Yingel, silakan pergi dan beri tahu mereka untuk masuk!"
}
return config
